// DeviceFacts gathers every device the targeted Catalyst Center manages
// and emits them as facts.
//
// It pages rather than fetching everything at once, so a controller
// managing a large fleet does not have to fit in the runner's memory. The
// emitted "devices" fact is a slice of maps rather than a typed struct
// because facts cross into CEL expressions, where a map is what a
// when_cel condition can actually index.
//
// It never reports Changed: reading an inventory does not alter it, and a
// fact gatherer that claimed otherwise would make every run look like it
// converged something.
func DeviceFacts(ctx context.Context, rc sdk.RunbookContext, device inventory.InventoryItem, params map[string]any) (collection.Result, error) {
	client, err := clientForDevice(rc, device, params)
	if err != nil {
		return collection.Result{}, err
	}
	defer func() { _ = client.Close() }()

	devices := make([]map[string]any, 0)
	err = client.EachDevice(ctx, pageSize(params), func(d catalystcenter.Device) error {
		devices = append(devices, map[string]any{
			"id":                  d.ID,
			"hostname":            d.Hostname,
			"management_ip":       d.ManagementIPAddress,
			"family":              d.Family,
			"series":              d.Series,
			"platform_id":         d.PlatformID,
			"software_type":       d.SoftwareType,
			"software_version":    d.SoftwareVersion,
			"role":                d.Role,
			"serial_number":       d.SerialNumber,
			"reachability_status": d.ReachabilityStatus,
			"collection_status":   d.CollectionStatus,
		})
		return nil
	})
	if err != nil {
		return collection.Result{}, fmt.Errorf("net.catalyst.device_facts: %w", err)
	}

	if err := rc.EmitFact("devices", devices); err != nil {
		return collection.Result{}, err
	}
	if err := rc.EmitFact("device_count", len(devices)); err != nil {
		return collection.Result{}, err
	}
	return collection.Result{Changed: false}, nil
}

// pageSize reads the optional page_size task parameter, falling back to a
// default that is large enough to fetch a small fleet in one request.
//
// YAML decodes an unquoted integer into an int, but a value that arrived
// through JSON would be a float64, so both are accepted. A zero or negative
// value falls back rather than erroring: it is a tuning knob, not a
// correctness one.
func pageSize(params map[string]any) int {
	const defaultPageSize = 500

	switch v := params["page_size"].(type) {
	case int:
		if v > 0 {
			return v
		}
	case float64:
		if v > 0 {
			return int(v)
		}
	}
	return defaultPageSize
}
